 Begin CmpMap 	# Compound Mapping
    Nin = 2 	# Number of input coordinates
 IsA Mapping 	# Mapping between coordinate systems
    MapA = 	# First component Mapping
       Begin TranMap 	# Compound Transformation Mapping
          Nin = 2 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          MapA = 	# Mapping for forward transformation
             Begin UnitMap 	# Unit (null) Mapping
                Nin = 2 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
             End UnitMap
          MapB = 	# Mapping for inverse transformation
             Begin MatrixMap 	# Matrix transformation
                Nin = 2 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                M0 = 1 	# Forward matrix value
                M1 = 0 	# Forward matrix value
                M2 = 2 	# Forward matrix value
                M3 = 1 	# Forward matrix value
                IM0 = 1 	# Inverse matrix value
                IM1 = 0 	# Inverse matrix value
                IM2 = -2 	# Inverse matrix value
                IM3 = 1 	# Inverse matrix value
                Form = "Full" 	# Matrix storage form
             End MatrixMap
       End TranMap
    MapB = 	# Second component Mapping
       Begin TranMap 	# Compound Transformation Mapping
          Nin = 2 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          MapA = 	# Mapping for forward transformation
             Begin UnitMap 	# Unit (null) Mapping
                Nin = 2 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
             End UnitMap
          MapB = 	# Mapping for inverse transformation
             Begin MatrixMap 	# Matrix transformation
                Nin = 2 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                M0 = 1 	# Forward matrix value
                M1 = 3 	# Forward matrix value
                M2 = 0 	# Forward matrix value
                M3 = 1 	# Forward matrix value
                IM0 = 1 	# Inverse matrix value
                IM1 = -3 	# Inverse matrix value
                IM2 = 0 	# Inverse matrix value
                IM3 = 1 	# Inverse matrix value
                Form = "Full" 	# Matrix storage form
             End MatrixMap
       End TranMap
 End CmpMap
